contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        c.depositsCount(); if (__ESBMC_reverted()) return;
        // fund c via its fallback using the flat low-level send is not allowed; instead send Ether in run by calling fallback is disallowed, so fund via receive of this contract then forward: use c.sendMoney? that is onlyOwner and sends out. Use fallback funding through c's payable receive? fallback is the only payable entry; shape rules forbid address cast. Instead, run may itself receive amount, and we assert on a state-only rule.
        uint balBefore = address(c).balance;
        uint cntBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdraw(0); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore && c.depositsCount() == cntBefore);
    }
    receive() external payable {}
}

